  "caveats": [
   "Inlästa tentor: alla Termin 7-tentor och omtentor 2017 till och med HT25 som finns i mappen (36 sessioner).",
   "Flervalsfrågornas rätta svar är avlästa från markeringarna i PDF:erna. Fritextfrågor följer tentans svarsmall. Vissa frågor från 2020–2022 saknar facit och är markerade som ej bekräftade.",
   "Frågor som berör flera ämnen är kopplade till flera ämnen och räknas då i varje. Fallfrågor med delfrågor är sammanfattade som en fråga.",
   "Ämnesindelningen är manuell men grov; närliggande delämnen är sammanslagna till huvudposter och frågorna bakom varje delämne syns under Vad har examinerats?.",
   "Fråga 25 på HT25 ordinarie (grundbehandling vid symtomgivande ateroskleros) har facit \"antikoagulantia och statin\", vilket avviker från vanlig praxis (trombocythämmare och statin). Facit är återgivet som det står.",
   "Kort: ämneskorten är hämtade från motsvarande uppslag i uppslagsboken (eller korta nyskrivna kort där uppslag saknas). Alla kort är studieunderlag och ska stämmas av mot kurslitteraturen."
  ]
