   "card": {
    "fk": "Prostatacancer är oftast adenokarcinom. Sjukdomen är ofta långsamt växande men kan vara aggressiv vid hög Gleason/ISUP, hög PSA-nivå, avancerat T-stadium eller metastaser.",
    "v": [
     "Riskfaktorer: ålder är viktigast. Ärftlighet ökar risken, särskilt vid flera nära släktingar eller tidig debut. BRCA2 är särskilt kopplat till högre risk och mer aggressiv sjukdom",
     "Lokaliserad sjukdom: ofta asymtomatisk. LUTS beror oftare på BPH än cancer",
     "Avancerad sjukdom: skelettsmärta, viktnedgång, anemi, hydronefros, hematuri eller neurologiska symtom vid medullakompression"
    ],
    "k": "—",
    "d": "Misstanke: riktad anamnes (ärftlighet, vattenkastning, skelettsymtom), prostatapalpation, PSA. Identifierar patienter som behöver SVF och skiljer cancertecken från vanlig BPH/infektion. PSA bör inte tas under misstänkt UVI/prostatit om inte stark cancersuspekt bild Välgrundad misstanke: PSA över gränsvärde: <70 år ≥3 µg/L, 70–80 år ≥5 µg/L, >80 år ≥7 µg/L. Halvera gränser vid 5-alfareduktashämmare. Malignitetsmisstänkt palpation eller urologisk biopsiindikation ger också välgrundad misstanke. Startar SVF och leder till snabb strukturerad utredning;",
    "b": "Radikal prostatektomi: kirurgiskt avlägsnande av prostata och sädesblåsor, ibland lymfkörtelutrymning. Oftast robotassisterad laparoskopi Extern strålbehandling: kurativ eller palliativ joniserande strålning mot prostata/prostatabädd/metastaser. Kan kombineras med hormonell behandling Hypofraktionering: färre fraktioner med högre dos per fraktion. Ultrahypofraktionering används vid vissa riskgrupper Brachyterapi: intern strålbehandling. Kan användas i vissa sammanhang;",
    "m": "Tentafälla – symtom: prostatacancer ger inte nödvändigtvis LUTS tidigt. Hög PSA eller palpationsfynd är viktigare än vattenkastningsbesvär för cancerutredning",
    "src": "t7-213"
   },
