   "card": {
    "fk": "Datortomografi är en form av röntgen som ger mer detaljerade bilder av organ än konventionell röntgen och hjälper att upptäcka sjukdomar och skador. Undersökningen anpassas efter organ och klinisk frågeställning.",
    "v": [
     "Indikation: anpassas efter organ och frågeställning; remissen ska tydligt ange vad som ska utredas",
     "Breda frågeställningar med många organ ger en kompromiss eftersom alla organ inte kan undersökas med optimal teknik (Region Dalarna)"
    ],
    "k": "—",
    "d": "Peroral kontrast: vanligen 2 % Omnipaque under 1 timme; 2 timmar vid abscess, misstänkt inflammation i ileocekalregionen, appendicit, divertikulit eller gynekologiska frågor; enbart vatten i 30 min vid isolerad pankreas-/lever-/ventrikel-/binjureundersökning Ingen peroral kontrast vid DT njurar/urinvägar, thorax eller stort trauma; ingen kontrast vid DT BÖS Intravenös kontrast: ges oftast med kontrastspruta (2–5 ml/s) via grön eller rosa venflon; hand vid gul venflon",
    "b": "Njurfunktion: nedsatt njurfunktion ger ökad risk för njurskada, god hydrering före och efter. Riskgrupper: äldre, diabetiker, hjärtsvikt, myelom, nyopererade, sepsis/hypovolemi/chock, nyligen iv-kontrast. Kreatinin-gränsvärde 150 (100 vid diabetes eller myelom) Ingen iv-kontrast: myelom med Bence-Jones-protein i urin; mastocytos; obehandlad hypertyreos; misstänkt/konstaterad tyreoideacancer med planerad radiojodbehandling Försiktighet: thyreostatikabehandlad hypertyreos Myastenia gravis/tymom: ingen jodkontrast;",
    "m": "Patienten måste kunna ligga stilla: oroliga patienter, många barn och utvecklingsstörda behöver ofta premedicinering/sedering, som initieras av remittent som också kontaktar narkos",
    "src": "t7-149"
   },
