   "card": {
    "fk": "Urotelial cancer i urinblåsa, njurbäcken, uretär och uretra. Vid diagnos är ca 80 % icke-muskelinvasiva (Ta, T1, Tis) och ca 20 % muskelinvasiva (T2–T4).",
    "v": [
     "Makroskopisk hematuri är vanligaste symtomet",
     "Sveda vid kissning, tät/ständig kissnödighet, återkommande UVI (1177)",
     "Riskfaktorer: rökning (ca 50–65 % hos män, ca 50 % hos kvinnor), aromatiska aminer (yrke), tidigare bäckenstrålning, cyklofosfamid, fenacetin, aristolochiasyra, schistosomiasis; Lynchs syndrom (särskilt övre urinvägar)"
    ],
    "k": "—",
    "d": "Primär utredning: DT-urografi, cystoskopi och cytologi på kastad urin (Paris-systemet; hög sensitivitet för höggradiga tumörer) TURB med detrusormuskel i separat prov; bimanuell palpation före och efter; checklista PDD eller NBI kan förbättra upptäckt av carcinoma in situ Misstänkt muskelinvasiv: FDG-PET-DT; MRT före TURB Övre urinvägscancer: immunhistokemi för MMR-proteiner (Lynch)",
    "b": "Alla opereras först med TUR-B Icke-muskelinvasiv: vid behov sköljningar i blåsan med cytostatika eller BCG; regelbundna cystoskopier Muskelinvasiv: vanligast cystektomi; strålbehandling (ofta + cytostatika) som alternativ; ca hälften botas Spridd: sällan bot, behandling bromsar och lindrar Efter cystektomi ny urinkanal: urostomi, tarmblåsa i buken eller ortotop ersättningsblåsa",
    "m": "Makrohematuri hos >50 år → SVF",
    "src": "t7-215"
   },
