   "card": {
    "fk": "Strålbehandling använder joniserande strålning (oftast fotoner) som ger DNA-skador (enkel- och dubbelsträngsbrott) och mitotisk celldöd; dosen anges i gray (Gy). Ges kurativt (ensam, med cytostatika eller pre-/postoperativt, t.ex. vid bröst-, rektal-, prostata-, lung- och blåscancer) eller palliativt mot lokala symtom.",
    "v": [
     "Fraktionering: många små fraktioner (ca 2 Gy) skonar normalvävnad och minskar sena biverkningar; hypofraktionering = större doser vid färre tillfällen",
     "Akuta biverkningar (inom ca 90 dagar, t.ex. dermatit, mukosit, diarré, cystit) går oftast över; sena biverkningar (fibros, strålproktit/-cystit, hjärt- och lungskada) är oftast kroniska och beror särskilt på fraktionsstorleken",
     "Palliativ strålbehandling lindrar lokala symtom, t.ex. 8 Gy x 1 mot smärtsam skelettmetastas; även vid medullakompression, hjärnmetastaser och blödande tumör"
    ],
    "k": "—",
    "d": "—",
    "b": "Process: fixering, planerings-DT (ev. MR), inritning av målvolym och riskorgan, dosplanering, verifiering av behandlingsläge och behandling (ca 15 min per session). Vid bröstcancer ges strålbehandling i regel efter bröstbevarande kirurgi och lokoregionalt vid nodpositivitet/hög risk.",
    "m": "Strålpneumonit (hosta, andfåddhet veckor–månader efter thoraxbestrålning) utreds med DT och behandlas med kortison.",
    "src": "t7-115"
   },
   "has_card": true,
   "investigation": false,
   "related": [
    "hjarnmetastaser",
    "medullakompression"
   ],
   "xcc": [
    "t7-115"
   ]
