   "card": {
    "fk": "Kolorektalcancer (colon- och rektalcancer) handläggs efter stadium, lokalisation (colon/rektum), MR-risk vid rektum, biomarkörer (MMR/MSI, RAS, BRAF, NTRK) och behandlingsmål. Uppslaget omfattar stadieindelad behandling, biomarkörer/målriktad behandling/immunterapi/strålbehandling, akuta tillstånd samt biverkningar och komplikationer.",
    "v": [
     "Kolonileus / malign obstruktion: Buksmärta i intervaller, meteorism, kräkningar, utebliven gas/avföring. Ofta vänstersidig stenoserande tumör.",
     "Perforation/peritonit: Akut svår buksmärta, peritoneal retning, feber/sepsis, fri gas. Kan vara tumörperforation eller proximal perforation vid obstruktion.",
     "Akut nedre GI-blödning / tumörblödning: Synligt blod, melena/hematochezi, anemi, yrsel/synkope. KRC ger oftare långsam blödning men akut blödning kan förekomma."
    ],
    "k": "—",
    "d": "MMR/MSI: dMMR/MSI-high: Ska bedömas eftersom det påverkar prognos, ärftlighetsmisstanke och behandling. Vid metastaserad sjukdom kan immunterapi vara förstahandsval. pMMR/MSS: Vanligaste situationen. Immunterapi har inte samma roll som vid dMMR/MSI-high. RAS-mutation: Prediktivt negativt för EGFR-hämmare. RAS/BRAF vildtyp, vänstersidig primärtumör, pMMR: Bästa situationen för EGFR-hämmare i metastaserad sjukdom, särskilt när respons önskas. RAS/BRAF vildtyp, högersidig primärtumör, pMMR: EGFR-hämmare har sämre effekt i första linjen än vid vänstersidig tumör. BRAF V600E-mutation: Ogynnsam prognostisk markör och behandlingsstyrande vid metastaserad sjukdom.",
    "b": "Koloncancer stadium 0 / carcinoma in situ / malign polyp med mycket låg risk: Endoskopisk radikal excision kan räcka om PAD visar lågriskfaktorer: fri marginal, ingen kärlinvasion, låg tumörbudding, låg/intermediär differentiering och säker komplett resektion. Koloncancer stadium I: Kirurgi med onkologisk kolonresektion och regional lymfkörtelutrymning. Ingen adjuvant cytostatika i normalfallet. Koloncancer stadium II: Kirurgi. Adjuvant cytostatika ges inte rutinmässigt men övervägs vid högriskfaktorer, till exempel T4, perforation, ileus/obstruktion, få analyserade lymfkörtlar, kärlinvasion, perineural invasion eller annan ogynnsam PAD. dMMR/MSI-high påverkar adjuvansbedömning.",
    "m": "Koloncancer stadium 0 / carcinoma in situ / malign polyp med mycket låg risk: Poängen är att mycket tidig cancer kan vara endoskopiskt botad, men PAD avgör om kompletterande tarmresektion behövs.",
    "src": "t7-024"
   },
