   "card": {
    "fk": "Aneurysm på bukaortan (AAA/BAA), definition ofta aorta ≥3 cm eller 1,5 x normalt segment. Degenerativ aneurysmsjukdom; kan vara asymtomatiskt eller rupturera med retro-/intraperitoneal blödning.",
    "v": [
     "Asymtomatiskt AAA: ofta asymtomatiskt; ev pulserande bukresistens. Smärta kan tala för expansion/ruptur",
     "Rupturerat AAA: klassisk triad: akut buk-/rygg-/flanksmärta, cirkulationspåverkan/synkope, pulserande bukresistens. Triaden saknas ibland"
    ],
    "k": "—",
    "d": "Asymtomatiskt AAA: ultraljud för screening/uppföljning. DT-angio inför operationsplanering. Screenas nationellt: 65-åriga män; hereditet kan motivera riktad kontroll Rupturerat AAA: klinisk diagnos vid instabil patient. DT-angio om tillräckligt stabil och det inte fördröjer åtgärd",
    "b": "Asymtomatiskt AAA: riskfaktorkontroll, rökstopp, ASA/statin vid aterosklerossjukdom enligt sammanhang, ultraljudskontroller. Operationsbedömning typiskt vid ≥5,5 cm hos män, ≥5,0 cm hos kvinnor, snabb tillväxt eller symtom. EVAR eller öppen operation Rupturerat AAA: larma kärlkirurg, anestesi, blodbank. Grova infarter, blodprodukter, permissiv hypotension tills kontroll av blödning om patienten är vaken/talbar. Akut EVAR om anatomi tillåter eller öppen operation",
    "m": "Tenta: 5,5 cm hos män (operationsgräns); tromb i aneurysmet räknas med i ytterdiametern",
    "src": "t7-052"
   },
