   "card": {
    "fk": "Chock är otillräcklig vävnadsperfusion och syrgasleverans med anaerob metabolism och hotande organsvikt. Indelas i hypovolem, distributiv (septisk, anafylaktisk, neurogen), kardiogen och obstruktiv chock; behandla orsaken och återställ perfusionen.",
    "v": [
     "Orsak: blödning, dehydrering, kräkningar, diarré, brännskada, tredje-rumsförlust vid ileus/pankreatit/sepsis",
     "Tidiga tecken: takykardi, kall periferi, konfusion, laktatstegring och oliguri",
     "Hypotension är ett sent och allvarligt tecken",
     "Kardiogen chock – överväg: hjärtinfarkt, arytmi, klaffel och akut hjärtsvikt",
     "Obstruktiv chock – misstänk vid: tamponad, massiv lungemboli eller övertryckspneumothorax"
    ],
    "k": "",
    "d": "",
    "b": "Vid blödning: blodprodukter enligt massiv transfusionsprincip, kirurgisk/interventionell blödningskontroll, tranexamsyra tidigt vid trauma enligt lokala riktlinjer, calcium vid massiv transfusion Vid dehydrering/tredje-rumsförlust: balanserad kristalloid i bolus och upprepad bedömning av effekt",
    "m": "Principen: stoppa förlusten och ersätt volymen",
    "src": "t7-245"
   },
