   "card": {
    "fk": "Lungcancer delas in i NSCLC och SCLC, med stadium, molekylärprofil (EGFR/ALK/ROS1/BRAF/KRAS/MET/RET/NTRK/ERBB2) och PD-L1 som styr behandlingen. Kortet samlar stadiebaserad behandling, biomarkörstyrt val av målriktad behandling/immunterapi, akuta tillstånd och komplikationer samt biverkningar av behandlingsregimerna.",
    "v": [
     "NSCLC stadium I: lokaliserad tumör utan regional/fjärrmetastas. Kurativ intention",
     "NSCLC stadium II: potentiellt kurativ sjukdom, ofta större tumör eller N1-sjukdom",
     "NSCLC stadium IIIA resektabelt i selekterade fall: lokoregionalt avancerad, heterogen grupp. Vissa IIIA är kirurgiskt resektabla efter MDK, framför allt begränsad N2/minimal N2 eller T3/T4 med tekniskt resektabel sjukdom"
    ],
    "k": "—",
    "d": "Utredningen ska fastställa diagnos, stadium, funktionsstatus och – vid palliativ inriktning – molekylärpatologisk typning DT är förstahandsmetod vid klinisk misstanke; lungröntgen kan användas men negativ lungröntgen utesluter inte cancer EGFR, BRAF, KRAS, MET exon 14-skipping, ERBB2, ALK, ROS1, RET, NTRK och PD-L1; NGS/multiplex rekommenderas Gäller framför allt vid avancerad NSCLC men är även relevant vid tidigt stadium då adjuvant/neoadjuvant målriktad eller immunterapi kan bli aktuellt Reflextestning på biopsi/cytologi rekommenderas. Testa om vid progress/recidiv efter systembehandling, särskilt efter TKI Vena cava superior-syndrom: snar DT thorax med intravenös kontrast.",
    "b": "NSCLC stadium I: kirurgi är förstahandsmetod om patienten är operabel. Standardingrepp är lobektomi med systematisk hilär/mediastinal lymfkörtelexploration. Sublobär resektion/segmentektomi kan övervägas vid små tumörer (<2 cm) och verifierat N0 eller vid nedsatt lungfunktion/samsjuklighet. Om patienten inte tål kirurgi ges kurativ stereotaktisk strålbehandling (SBRT) där tekniskt möjligt NSCLC stadium II: kirurgi om resektabelt och patienten är operabel. Postoperativ adjuvant platinumbaserad cytostatika ges/övervägs vid stadium IB eller högre, tydligast stadium II–IIIA. Vid EGFR-positiv resekerad sjukdom kan adjuvant osimertinib ges;",
    "m": "Tenta, misstänkt lungcancer: skriv alltid ”SVF lungcancer” vid VGM och därefter DT/PET-DT/vävnadsdiagnos beroende på kurativ eller palliativ intention",
    "src": "t7-122"
   },
   "has_card": true,
   "investigation": false,
   "related": [
    "epidemiologi-och-riskfaktorer-for-cancer",
    "stralbehandling"
   ],
