   "card": {
    "fk": "FAST är en kort, riktad ultraljudsundersökning tidigt i traumaomhändertagandet för att påvisa fri vätska (oftast blod) i bukhålan eller hjärtsäcken. Den kan inte bekräfta eller utesluta skador på inre organ.",
    "v": [
     "Trubbigt eller penetrerande våld mot bålen där snabb påvisning av blödning kan avgöra om akut operation behövs",
     "Störst nytta vid cirkulatorisk instabilitet (systoliskt blodtryck ≤90 mmHg) när patienten kan opereras direkt vid fynd av blod (evidensstyrka 3, begränsad)",
     "Hos cirkulatoriskt stabila patienter (>90 mmHg) är underlaget otillräckligt"
    ],
    "k": "—",
    "d": "Fyra områden: hjärtsäcken, höger övre kvadrant (runt levern och mellan lever och njure), vänster övre kvadrant (runt mjälten) och bäckenet (bakom urinblåsan) Vätska syns som mörk strimma eller mörkt, lågekogent område; koagulerat blod ser oftare ljusare ut Tar normalt 3-5 minuter; utförs av tränad akutläkare eller kirurg Sensitivitet 69-100 % beroende på utförarens skicklighet (i en studie 73 % med <25 undersökningar, 88 % med 25-50, 100 % med >50); specificitet 96-100 %",
    "b": "Retroperitoneala blödningar (t.ex. njur- eller bäckenskador) syns inte eftersom blodet ofta inte når bukhålan Intrakapsulära lever- eller mjältskador kan ge negativt FAST Undersökning tidigt i förloppet kan missa blödning som ännu inte blivit tillräckligt stor Ingen strålning och låg kostnad (cirka 200-250 kr per undersökning enligt källan)",
    "m": "Negativt FAST utesluter inte skada: retroperitoneal blödning och intrakapsulär lever-/mjältskada missas",
    "src": "t7-084"
   },
