   "card": {
    "fk": "Kolorektalcancer omfattar cancer i colon och rektum. Behandlingen styrs av stadium, lokalisation (colon eller rektum), MMR/MSI-status och RAS/BRAF-status samt patientens status och behandlingsmål. Colon och rektum behandlas olika: rektum utifrån MR-risk, colon främst med kirurgi ± adjuvant cytostatika.",
    "v": [
     "Kolonileus/malign obstruktion: buksmärta i intervaller, meteorism, kräkningar, utebliven gas/avföring. Ofta vänstersidig stenoserande tumör",
     "Perforation/peritonit: akut svår buksmärta, peritoneal retning, feber/sepsis, fri gas. Kan vara tumörperforation eller proximal perforation vid obstruktion",
     "Akut nedre GI-blödning/tumörblödning: synligt blod, melena/hematochezi, anemi, yrsel/synkope. KRC ger oftare långsam blödning men akut blödning kan förekomma"
    ],
    "k": "—",
    "d": "dMMR/MSI-high: ska bedömas eftersom det påverkar prognos, ärftlighetsmisstanke och behandling. Vid metastaserad sjukdom kan immunterapi vara förstahandsval. Särskilt starkt för immunterapi pMMR/MSS: vanligaste situationen; immunterapi har inte samma roll som vid dMMR/MSI-high RAS-mutation: prediktivt negativt för EGFR-hämmare RAS/BRAF vildtyp, vänstersidig primärtumör, pMMR: bästa situationen för EGFR-hämmare i metastaserad sjukdom, särskilt när respons önskas.",
    "b": "Stadium 0/carcinoma in situ/malign polyp med mycket låg risk: endoskopisk radikal excision kan räcka om PAD visar lågriskfaktorer: fri marginal, ingen kärlinvasion, låg tumörbudding, låg/intermediär differentiering och säker komplett resektion. PAD avgör om kompletterande tarmresektion behövs Stadium I (T1–T2 N0): kirurgi med onkologisk kolonresektion och regional lymfkörtelutrymning. Ingen adjuvant cytostatika i normalfallet. Botande kirurgi är huvudprincip Stadium II (N0 men djupare växt): kirurgi.",
    "m": "Stadium III (tentafråga): stadium III = lymfkörtelpositiv; operation räcker inte, adjuvant behandling tillkommer",
    "src": "t7-121"
   },
