   "card": {
    "fk": "Urinvägsobstruktion ger hydronefros och kan vara supravesikal (t.ex. uretärsten, tumör, PUJ-stenos), intravesikal eller subvesikal (BPH, prostatacancer, uretrastriktur). Bilateral obstruktion eller obstruktion med infektion (avstängningspyelit) kräver akut avlastning.",
    "v": [
     "Misstänk: uretärsten (vanligast), malign obstruktion (prostata-, blås-, uretärcancer, körtelmetastaser) eller subvesikalt hinder/urinretention",
     "Typisk klinik: flanksmärta, stigande kreatinin, infektion/urosepsis eller asymtomatisk hydronefros på DT"
    ],
    "k": "",
    "d": "Kontroll kreatinin, elektrolyter, urinvägsinfektion/urosepsis",
    "b": "Subvesikalt hinder: KAD. Supravesikalt hinder: akut avlastning med nefrostomi eller uretärstent; vid avstängningspyelit antibiotika + akut avlastning",
    "m": "Hydronefros/njursvikt: kontrollera kreatinin, elektrolyter och urinvägsinfektion/urosepsis; akut avlastning (nefrostomi eller uretärstent)",
    "src": "t7-204"
   },
