   "card": {
    "fk": "Ultraljud skapar rörliga bilder av inre organ som hjärta, lever och blodkärl. Det används för att ställa diagnos eller kontrollera effekt av tidigare behandling.",
    "v": [
     "Användning: buk, gallvägar, njurar, ben och armar, hals, könsorgan, skador på muskler, senor och leder",
     "Exempel på skäl: buksmärta, onormala provsvar, känd knöl, viktförändringar",
     "Doppler: vid misstanke om blodpropp kan blodflödet mätas"
    ],
    "k": "",
    "d": "Förberedelse buk/gallblåsa/kontrastultraljud: fasta 4 timmar (diabetiker kan äta något litet vid behov) Njurar/urinblåsa/lilla bäckenet: kissa inte före; ben, armar, hals: ingen särskild förberedelse Kontrastultraljud: kontrast injiceras via venkateter",
    "b": "Säkerhet: vanligt ultraljud på kroppens utsida gör inte ont (även om undersökaren ibland trycker hårt) och det finns inga bevis för att ultraljud skadar; Vävnadsprovtagning: blodförtunnande kan behöva sättas ut och blodprov tas för att bedöma blödningsrisk",
    "m": "Ultraljud är strålfritt och realtidsbaserat men operatörsberoende; dåligt för fri gas, retroperitoneala lymfkörtlar och skymda organ (tarmgas, obesitas).",
    "src": "t7-151"
   },
