   "card": {
    "fk": "Ljumskbråck delas in i lateralt/indirekt (lateralt om a. epigastrica inferior genom djupa inguinalringen) och medialt/direkt (genom Hesselbachs triangel medialt om a. epigastrica inferior). Vanligt hos män; klinik räcker ofta.",
    "v": [
     "Typiskt ljumskbråck: utbuktning i ljumske som ökar vid hosta/ansträngning och minskar i liggande; tryckkänsla/dragande smärta"
    ],
    "k": "—",
    "d": "Ofta klinisk diagnos. Vid oklarhet: ultraljud ljumskar, DT eller MR ljumskar beroende på tillgänglighet/frågeställning",
    "b": "Ljumskbråck hos man, vanlig metod: öppen Lichtenstein-nätplastik kan göras dagkirurgiskt och ofta i lokalbedövning. Laparoskopisk TEP/TAPP vid bilateralt bråck, recidiv efter öppen op eller särskilda skäl Ljumsk-/femoralbråck hos kvinna, vanlig metod: laparoskopisk/preperitoneal metod rekommenderas ofta som förstahandsval eftersom femoralkanalen då täcks och femoralbråck kan upptäckas",
    "m": "Tentafälla (man): ljumskbråck är mycket vanligare hos män; klinik räcker ofta. Alla män med små symtom måste inte opereras akut",
    "src": "t7-041"
   },
