   "card": {
    "fk": "Hjärnmetastaser kan ge ökat intrakraniellt tryck, fokalneurologi och kramper. Vanligaste primärtumörer är lungcancer, bröstcancer (särskilt HER2+ och TNBC) och malignt melanom.",
    "v": [
     "Typiska signaler: huvudvärk, illamående/kräkning, fokalneurologi, kramper, personlighetsförändring",
     "Vanligast vid lungcancer; vid bröstcancer särskilt HER2+ och TNBC; även malignt melanom"
    ],
    "k": "—",
    "d": "Akut neurologstatus MR hjärna om möjligt, DT akut vid instabil/akuta symtom Bedöm steroidbehov och kontakt med onkolog/neurokirurg",
    "b": "Betametason vid symtomgivande ödem enligt lokal rutin Antiepileptika vid kramper Stereotaktisk strålning, helhjärnsstrålning eller kirurgi beroende på antal, storlek, symtom, extracerebral sjukdom och prognos",
    "m": "Skriv inte bara \"palliativ vård\": många kan få aktiv lokal behandling",
    "src": "t7-136"
   },
