   "card": {
    "fk": "Kronisk extremitetsischemi orsakas av ateroskleros med otillräckligt flöde. Spänner från claudicatio (ansträngningsutlöst) till kronisk extremitetshotande ischemi (CLTI) med vilovärk, sår och nekros.",
    "v": [
     "Claudicatio: ateroskleros ger otillräckligt flöde vid arbete. Smärta i vad/lår/säte efter viss gångsträcka som försvinner i vila. Ansträngningsutlöst smärta; kalla fötter; svaga pulsar. Ingen vilovärk/sår vid ren claudicatio",
     "CLTI/kritisk ischemi: avancerad PAD där perfusionen inte räcker i vila eller för sårläkning. Vilovärk särskilt nattetid, ischemiskt sår/nekros/gangrän, sår på tå/häl, infektion kan tillkomma"
    ],
    "k": "—",
    "d": "Claudicatio: ABI/tåtryck. Duplex/DT-angio/MR-angio om kirurgi/endovaskulär åtgärd övervägs CLTI: ABI kan vara falskt högt; tåtryck/TcPO2 viktigt. Duplex/DT-angio för revaskulariseringsplan. Bedöm sår, infektion, osteit, diabetesfot",
    "b": "Claudicatio: rökstopp, gångträning, statin, trombocythämmare, BT/diabeteskontroll. Revaskularisering bara vid invalidiserande symtom trots konservativ behandling eller proximal lämplig lesion CLTI: smärtlindring, sårvård, antibiotika vid infektion, riskfaktorer, revaskularisering endovaskulärt eller bypass. Amputation endast när extremiteten ej går att rädda eller patientnytta saknas",
    "m": "Claudicatio som utvecklas till sår/vilovärk = kritisk/extremitetshotande ischemi och ska inte bara gångtränas",
    "src": "t7-049"
   },
   "has_card": true,
