   "card": {
    "fk": "Målriktad behandling riktas mot specifika molekylära förändringar i tumören med tyrosinkinashämmare eller monoklonala antikroppar; biomarkörer styr valet. Exempel: EGFR-/ALK-hämmare vid lungadenocarcinom, trastuzumab vid HER2+ bröstcancer, EGFR-antikroppar (vid RAS-vildtyp) och bevacizumab (VEGF) vid kolorektalcancer.",
    "v": [
     "RAS-mutation: Prediktivt negativt för EGFR-hämmare.",
     "RAS/BRAF vildtyp, vänstersidig primärtumör, pMMR: Bästa situationen för EGFR-hämmare i metastaserad sjukdom, särskilt när respons önskas.",
     "RAS/BRAF vildtyp, högersidig primärtumör, pMMR: EGFR-hämmare har sämre effekt i första linjen än vid vänstersidig tumör."
    ],
    "k": "",
    "d": "",
    "b": "RAS-mutation: EGFR-hämmare ges inte. Vid metastaserad sjukdom används cytostatika-dubblett/triplett ± bevacizumab beroende på behov av respons och patientstatus. RAS/BRAF vildtyp, vänstersidig primärtumör, pMMR: FOLFOX eller FOLFIRI + EGFR-hämmare kan övervägas i första linjen. Alternativ är dubblett + bevacizumab eller dubblett utan antikropp om biologiskt läkemedel inte passar. RAS/BRAF vildtyp, högersidig primärtumör, pMMR: Dubblett + bevacizumab är ofta förstahandsprincip; dubblett utan antikropp om antikropp inte passar. EGFR-hämmare kan bli aktuellt i särskilda situationer/linjer. BRAF V600E-mutation: Första linjen ofta dubblett/triplett + bevacizumab beroende på behov av respons och patientstatus. Vid senare linje: enkorafenib + cetuximab är etablerad målinriktad behandling. NTRK-fusion: Efter minst två behandlingslinjer kan NTRK-riktad behandling med larotrektinib eller entrektinib övervägas vid gott performance-status. Bevacizumab / angiogeneshämning: Används i metastaserad behandling, särskilt vid högersidig tumör, RAS/BRAF-mutation eller när EGFR-hämmare inte passar. Sätts ut i god tid inför större kirurgi. EGFR-hämmare: cetuximab/panitumumab: Kombineras ofta med FOLFOX eller FOLFIRI. Kan även användas med enkorafenib vid BRAF V600E i senare linje.",
    "m": "RAS-mutation: RAS-mut = tänk “ingen cetuximab/panitumumab”.",
    "src": "t7-112"
   },
