    "b": "Vätska: balanserad kristalloid vid hypoperfusion, men följ effekt och risk för övervätskning Antibiotika: bred antibiotika snabbt efter odlingar om det inte fördröjer behandlingen orimligt Vasopressor: noradrenalin är vanligt förstahandsval vid kvarstående hypotension efter adekvat vätska och distributiv chock",
