   "card": {
    "fk": "Vård i livets slutskede är palliativ vård under den sista tiden i livet, efter ett brytpunktssamtal, där målet är att lindra symtom och främja livskvalitet snarare än att förlänga livet. Det handlar om vårdens inriktning, inte en fast tidsperiod: det kan röra sig om timmar, dagar, veckor eller månader.",
    "v": [
     "Döende: livsviktiga funktioner sviktar och symtom visar att döden är nära",
     "Dominerande symtom: smärta, illamående, ångest, andnöd, trötthet (fatigue), rosslig andning och förvirring",
     "Tidig fas: livsförlängande och palliativa insatser kan pågå parallellt; sen fas: döden är oundviklig inom överskådlig tid"
    ],
    "k": "—",
    "d": "—",
    "b": "—",
    "m": "Vidbehovsordination ska finnas: Socialstyrelsen anger att patienter i livets slutskede bör ha vidbehovsordination mot smärta och ångest, samt vid behov mot illamående, andnöd och rosslighet (ofta injektion för säkrare upptag)",
    "src": "t7-144"
   },
