   "card": {
    "fk": "Cancerepidemiologi i Sverige: prostatacancer är vanligast, lungcancer orsakar flest cancerdödsfall och tobak är den enskilt viktigaste förebyggbara riskfaktorn; hög ålder är starkaste riskfaktorn för de flesta cancerformer. Exempel på riskmönster: prostatacancer och myelom.",
    "v": [
     "Prostatacancer: ålder är viktigast. Ärftlighet ökar risken, särskilt vid flera nära släktingar eller tidig debut. BRCA2 är särskilt kopplat till högre risk och mer aggressiv sjukdom",
     "Myelom: högre ålder, manligt kön, hereditet/familjär risk och föregående MGUS/smouldering är centrala riskmönster",
     "Myelom är framför allt en sjukdom hos äldre vuxna"
    ],
    "k": "—",
    "d": "—",
    "b": "—",
    "m": "Myelom, tentasvar: diffusa symtom hos äldre med ryggsmärta/anemi/hög SR bör väcka misstanke",
    "src": "t7-096"
   },
