   "card": {
    "fk": "Övre gastrointestinal blödning: orsakerna ulcusblödning, esofagusvaricer, Mallory-Weiss och cancerblödning skiljs åt i klinik, utredning och akut behandling.",
    "v": [
     "Ulcusblödning: hematemes, melena, synkope, takykardi/hypotension. Risk: NSAID, ASA, antikoagulantia, H. pylori",
     "Esofagusvaricer: hematemes/melena hos patient med cirros/portal hypertension, ascites, ikterus, spider naevi",
     "Mallory-Weiss: hematemes efter upprepade kräkningar/alkohol. Ofta självläkande slemhinnerift vid gastroesofageala övergången"
    ],
    "k": "—",
    "d": "Ulcusblödning: ABCDE, vitalparametrar, Hb, TPK, PK/INR/APTT, krea, leverstatus, blodgruppering/BAS/MG. Gastroskopi efter stabilisering, akut vid stor blödning Esofagusvaricer: som ovan + leverprover, koagulation. Akut gastroskopi. Bedöm encefalopati och infektion Mallory-Weiss: gastroskopi om pågående blödning eller osäker diagnos Cancerblödning: gastroskopi med biopsi efter stabilisering. DT/staging senare",
    "b": "Ulcusblödning: syrgas vid behov, 2 grova infarter, vätska/blod, reversera antikoagulation vid behov, PPI i.v. vid hög-risk ulcus, endoskopisk hemostas. Kirurgi/angioembolisering vid okontrollerad blödning/reblödning efter endoskopi Esofagusvaricer: ABCDE, blod restriktivt men adekvat, terlipressin/vasoaktiv behandling, antibiotikaprofylax, endoskopisk ligatur. Ballong/stent/TIPS vid okontrollerad blödning Mallory-Weiss: stabilisering. Endoskopisk behandling om aktiv blödning Cancerblödning: stabilisering, endoskopi; palliativ strålning/intervention kan behövas vid tumörblödning",
    "m": "Ulcus: hemodynamisk stabilisering före skopi. Tranexamsyra är inte rutin. Forrestklass styr risk och PPI/endoskopi",
    "src": "t7-004"
   },
