    "b": "Akut kärlkirurgkontakt, heparin iv om ej kontraindicerat, smärtlindring, vätska, håll extremiteten skyddad Revaskularisering: embolektomi, trombektomi, kateterledd trombolys, endovaskulär intervention eller bypass Fasciotomi vid reperfusions-/kompartmentrisk",
