   "card": {
    "fk": "Njurar och urinvägar utreds främst med ultraljud (hydronefros, cystor, tumörer, stenar) och DT urinvägar/DT-urografi (tumörer, hematuri, stenar m.m.). Valet styrs av frågeställningen.",
    "v": [
     "Ultraljud njurar: förändringar i storlek/ekogenicitet, njurcystor, njurtumörer, misstänkt njurvenstrombos, hydronefros, njurstenar",
     "DT urinvägar: tumörer, makroskopisk hematuri, infektion/inflammation, komplicerade njurcystor, trauma, hydronefros, missbildningar, konkrement, njurartärstenos, njurdonationsutredning"
    ],
    "k": "—",
    "d": "Ultraljud visar: storleks- och ekoförändringar, tumörers storlek och förhållande till omgivningen, ibland njurvenstrombos, hydronefros (utmärkt för att påvisa/utesluta), stenar även icke röntgentäta, parenkymcirkulation med färgdoppler Generella förändringar i njuren är ofta svåra att artbestämma DT-urografi: patienten dricker 0,5 l vatten under 1 timme och tömmer inte blåsan; typiskt 30 ml jodkontrast i en fas (enligt källan)",
    "b": "Ultraljud: inga förberedelser, inget kontrastmedel; ger ingen information om njurfunktion; ser inte alla stenar, särskilt inte små DT: överkänslighet mot jodkontrast är relativ kontraindikation (premedicinering kan användas); strålrisken ska beaktas, särskilt hos barn och unga; lågstråldosprotokoll vid stenfrågor",
    "m": "Hydronefros säger inget om njurfunktion, och avflödeshinder kan finnas utan hydronefros",
    "src": "t7-175"
   },
   "has_card": true,
   "investigation": false,
   "related": [
    "njurcancer"
   ],
   "xcc": [
    "t7-175",
    "t7-177"
   ]
