   "card": {
    "fk": "Handläggning av traumatiska sår (bedömning, rengöring, anestesi, val av slutningsmetod) och principer för excision och suturering i hud.",
    "v": [
     "Anamnes: skademekanism (skärning, krossning, bett, stick), tid sedan skadan, rent eller kontaminerat, tetanusskydd",
     "Sennära sår: sår på handryggen och ytliga skador hos barn bedöms som sennära",
     "Tidsgräns primärslutning: generellt inom 8 timmar (längre ju mer kranialt); ansikte upp till 24 timmar; förorenat sår på foten inom 3 timmar"
    ],
    "k": "—",
    "d": "Inspektera såret, utesluta främmande kropp, undersök distalstatus (cirkulation, känsel, rörlighet, kraft) Rengöring: tvål och rikligt med vatten (koksalt eller kranvatten), avlägsna grus och partiklar Anestesi (enligt Viss): infiltration lidokain 5 eller 10 mg/ml, buffrad och något varm lindrar; topikalt kompress med lidokain >20 min eller LAT-gel i såret Excision (Läkartidningen): snitt parallellt med sprickriktningen (Langers linjer); spolformad excision; underminering 5–10 mm vid behov; nyp inte lesionen med pincett (försvårar PAD)",
    "b": "Metodval (Viss): primärsutur om rengjort, reviderat och ej synligt kontaminerat; vävnadslim (cyanoacrylat) för små sår utan spänning (lägre hållfasthet); Steri-Strips för ytliga sår eller som förstärkning; fördröjd sutur efter 4–5 dagar vid kraftigt kontaminerade men ej devitaliserade sår Suturmaterial (Läkartidningen): skärande atraumatisk nål, monofil tråd; oftast icke-resorberbar hudsutur; grovlek 6-0 eller 5-0 i ansiktet, 4-0 till 3-0 på övrig kropp; resorberbara subkutana suturer i djupa sår Teknik: sy lager mot lager, börja i ena änden och sy växelvis mot mitten; sårkanterna ska evereras; enstaka enkla suturer ger oftast bäst resultat;",
    "m": "Endast rena sår läker – rengör noggrant och revidera till frisk, blödande vävnad",
    "src": "t7-078"
   },
