    "b": "Radikal prostatektomi: kirurgiskt avlägsnande av prostata och sädesblåsor, ibland lymfkörtelutrymning. Oftast robotassisterad laparoskopi Kastrationsbehandling/ADT: sänker testosteron till kastrationsnivå: GnRH-agonist + flareskydd initialt, GnRH-antagonist eller ablatio testis",
    "m": "Radikal prostatektomi: erektil dysfunktion är en av de viktiga komplikationerna, tillsammans med urininkontinens och anastomosstriktur",
