   "card": {
    "fk": "Screening är systematisk undersökning av en befolkningsgrupp för att hitta personer med ett tillstånd som medför hög risk för framtida ohälsa, så att det kan åtgärdas tidigt. Screening av grupper med redan känd risk ingår inte i begreppet.",
    "v": [
     "Syfte: upptäcka tillstånd som kan leda till död, allvarlig skada, funktionsnedsättning eller stora samhällskostnader",
     "Socialstyrelsens modell har 15 kriterier med ursprung i WHO:s screeningkriterier",
     "Mammografiscreening: kvinnor 40–74 år (Socialstyrelsen, rekommendation A); frivilligt och avgiftsfritt",
     "Efter 74 år rekommenderas screening inte (inga visade fördelar, risk för behandling av cancer som aldrig gett symtom)",
     "Ärftligt ökad risk: kan behöva andra intervall eller metoder"
    ],
    "k": "",
    "d": "",
    "b": "",
    "m": "Nytta måste överväga skada: hälsovinsterna ska överväga de negativa effekterna (kriterium 9), t.ex. överdiagnostik",
    "src": "t7-098"
   },
