   "card": {
    "fk": "Fimosis är trång förhud som inte går att dra tillbaka över ollonet. Inte alla med fimosis behöver åtgärd; kortison prövas först och kirurgi övervägs om det inte hjälper.",
    "v": [
     "Trång förhud som inte går att dra tillbaka",
     "Inflammation under/i förhuden (balanit/balanopostit) kan ge eller förvärra trånghet",
     "Lichen sclerosus: vit sklerotisk hud, fissurer, klåda, trång förhud, fimos och meatusstenos (balanitkälla)"
    ],
    "k": "—",
    "d": "Klinisk bedömning av förhud och glans Vid inflammation: anamnes (hudsjukdom, allergi, hygien), penselprov för odling, ev. biopsi vid utebliven effekt eller misstanke om (pre)malignitet (enligt balanitöversikt)",
    "b": "Första steg: lokal kortisonbehandling Studie hos 41 pojkar med potent steroidsalva (grupp 4) en gång dagligen med försiktig tillbakadragning: lyckat hos 35 inom högst 3 månader; efter avslut återkom fimosen helt hos 12 och delvis hos 7. Författarna föreslår potent steroid i högst 4 veckor som förstahandsval vid behandlingskrävande fimos Kirurgi om kortison inte hjälper: omskärelse (hela förhuden bort, vanligast), dorsalklipp (trånga delen klipps upp, förhuden viks åt sidorna), förhudsplastik (vidgning med några små snitt, förhuden kan dras tillbaka)",
    "m": "Fimosis är riskfaktor för peniscancer och för balanopostit",
    "src": "t7-209"
   },
