   "specialty": "Urologi",
   "kind": "diagnos",
   "akut": true,
   "xcc": [
    "t7-206",
    "t7-207"
   ],
   "has_card": true,
   "investigation": false,
   "related": [
    "benigna-skrotala-forandringar",
    "manlig-infertilitet",
    "prostatacancer"
   ],
   "card": {
    "fk": "Skrotal smärta med hastig debut, med eller utan svullnad och rodnad. Syftet med bedömningen är att snabbt utesluta testistorsion. Underlag främst från barn/ungdomar.",
    "v": [
     "Fråga om: ålder, tidigare episoder, trauma, hereditet, systemiska symtom, dysuri, ev. oskyddat samlag",
     "Status: allmäntillstånd, buk, ljumskar, inspektion (blue dot sign hos ca 10–23 %), palpation, Prehns tecken, genomlysning, kremasterreflex",
     "Vanligast i tonåren (65 % vid 12–18 år); ca 400 pojkar <15 år drabbas per år i Sverige",
     "Klassiskt: akut, kraftig, ensidig testikelsmärta, även i vila",
     "Fynd: horisontell, högt stående, öm testikel; ibland palpabel 'knuta' ovanför testikeln"
    ],
    "k": "",
    "d": "Twist-poäng (0–7): svullen testikel 2, hård testikel 2, uppdragen testikel 1, illamående/kräkning 1, avsaknad kremasterreflex 1. 0–2 låg risk, 3–4 intermediär (ultraljud + kirurg/urolog), 5–7 hög risk (akut exploration) Ultraljud med doppler: sensitivitet 95–100 %, specificitet 85–95 % för torsion; whirlpool sign diagnostiskt Lab: generellt ingen; urinsticka vid misstänkt epididymit",
    "b": "Torsion: akut exploration, detorsion och bilateral orkidopexi; orkidektomi vid nekros Torsion av skrotala bihang: oftast NSAID; exploration vid osäker diagnos eller kvarstående smärta Epididymit: NSAID om urinprov negativt; antibiotika vid bakteriell infektion/immunsuppression Idiopatiskt skrotalödem: går över på några dagar; antihistamin kan hjälpa",
    "m": "Testistorsion ska alltid uteslutas först; ingen metod kan helt utesluta den, osäkerhet ska leda till akut exploration",
    "src": "t7-206"
   },
