   "card": {
    "fk": "Irreponibelt, inklämt/inkarcererat och strangulerat bråck är olika grader med olika handläggningskonsekvens. Strangulerat bråck = störd blodförsörjning till tarm/omentum och kräver akut operation.",
    "v": [
     "Inkarcererat bråck: fastnat och går inte att reponera. Strangulerat bråck: nedsatt eller upphävd blodförsörjning med ischemirisk.",
     "Akut handläggning av misstänkt strangulerat bråck: snabb bedömning, kirurgkontakt och akut operation efter vätska, smärtlindring och antibiotika."
    ],
    "k": "—",
    "d": "Bedöm ABCDE och vitalparametrar: identifiera sepsis, chock, dehydrering, aspirationrisk och smärtgrad. Motivering: akut bråck med ileus/strangulation kan snabbt bli livshotande. Status och reponibilitet: undersök bråcklokalisation, ömhet, hud, peritonit och bukdistension. Bedöm men forcera inte reponering vid strangulationsmisstanke. Motivering: smärtsam irreponibel knöl + allmänpåverkan/hudrodnad/peritonit talar för akut op. Infarter, prover och vätska: PVK, blodstatus, elektrolyter, kreatinin, CRP, laktat/blodgas vid påverkan, BAS-test vid op-risk, Ringer/Plasmalyte. Motivering: ileus ger dehydrering och elektrolytrubbning; op kan behövas snabbt.",
    "b": "Fasta, smärta och illamående: fasta, opioid titrerat, antiemetika. Ventrikelsond vid kräkning/ileus. Motivering: minskar aspiration och avlastar proximal tarm. Antibiotika: ges vid misstänkt strangulation, ischemisk tarm, perforation eller sepsis enligt lokal rutin. Motivering: täcker translokation/peritonit vid tarmischemi",
    "m": "Reponera inte slentrianmässigt vid peritonit, hudrodnad, sepsis, lång duration eller stark misstanke om ischemi",
    "src": "t7-046"
   },
