   "card": {
    "fk": "Inflammation i tarmdivertikel, oftast med vänstersidig fossasmärta. Okomplicerad divertikulit är inte automatiskt antibiotika/operation; komplicerad divertikulit kräver kirurgisk vård.",
    "v": [
     "Akut divertikulit: oftast vänster fossa-smärta, feber, CRP-stegring, ändrade avföringsvanor; peritonit vid perforation"
    ],
    "k": "—",
    "d": "Basprover: blodstatus, CRP, elektrolyter/krea; urinsticka kan vara missvisande pga retning mot urinvägar Bild: DT buk med iv kontrast vid första skov, osäker diagnos, misstänkt abscess/perforation eller påverkan",
    "b": "Okomplicerad, initialt: smärtlindring, vätska/kostråd, observation/poliklinisk handläggning om patienten är opåverkad och diagnosen säker Okomplicerad, definitivt: antibiotika behövs ofta inte vid mild okomplicerad divertikulit; åter vid försämring/utebliven förbättring Komplicerad, initialt: inläggning, fasta/tarmvila, i.v. vätska, smärtlindring, antibiotika, sepsisbehandling Komplicerad, definitivt: abscess – perkutant dränage vid större/tillgänglig abscess; fri perforation/peritonit – akut kirurgi, t.ex. resektion/stomi eller lavage enligt situation",
    "m": "Tentapoäng: okomplicerad och opåverkad patient kan ofta följas utan antibiotika; komplicerad kräver kirurgisk vård",
    "src": "t7-028"
   },
