   "card": {
    "fk": "Obesitaskirurgi vid avancerad obesitas: indikationer, metoder (gastric bypass, sleeve gastrektomi, duodenal switch/SADI-varianter) och livslång postoperativ uppföljning.",
    "v": [
     "Indikationer: BMI ≥40, eller BMI ≥35 med obesitasrelaterad samsjuklighet (t.ex. typ 2-diabetes, sömnapné, hypertoni); lägre BMI endast i selekterade fall (t.ex. svårbehandlad typ 2-diabetes).",
     "Bedömning inför kirurgi: BMI, metabol samsjuklighet, tidigare viktbehandling, alkohol/droger, psykiatri, nutrition, operationsrisk och förmåga till livslång uppföljning"
    ],
    "k": "—",
    "d": "Gastric bypass, preop: nutrition, leversänkande kost enligt rutin, anestesirisk, diabetesläkemedel Sleeve, preop: som ovan. Refluxanamnes är viktig Duodenal switch/SADI: noggrann specialistbedömning, nutritionsrisk",
    "b": "Indikationer: kirurgi först efter multidisciplinär bedömning och informerat beslut Gastric bypass: liten ventrikelficka kopplas till tunntarm; restriktiv och hormonell/metabol effekt. Roux-en-Y gastric bypass. Ofta bra vid typ 2-diabetes och reflux jämfört med sleeve Sleeve gastrektomi: stor del av magsäcken tas bort; tubformad ventrikel. Vanlig metod. Laparoskopisk sleeve Duodenal switch/SADI-varianter: mer kraftig metabol/malabsorptiv effekt vid extrem obesitas i selekterade fall. Används mer selektivt",
    "m": "Efter gastric bypass/sleeve: måste nämna livslång substitution och uppföljning",
    "src": "t7-011"
   },
