   "card": {
    "fk": "Multipelt myelom är en plasmacellssjukdom (maligna differentierade B-celler) med M-komponent, och diagnos/behandlingsindikation bygger på CRAB eller myelomdefinierande biomarkörer. Uppslaget täcker sjukdomsgrupper (MGUS, smouldering, myelom, solitärt plasmocytom, AL-amyloidos), patofysiologi, symtom, utredning, risk, behandling, akuta komplikationer, läkemedel, understödjande behandling, uppföljning och cytogenetik.",
    "v": [
     "MGUS: M-komponent utan myelomdefinierande organpåverkan och utan kriterier för myelom; vanligt hos äldre. Oftast asymtomatiskt; ingen CRAB orsakad av plasmacellssjukdom",
     "Smouldering/asymtomatiskt myelom: högre tumörbörda än MGUS men ännu ingen myelomdefinierande händelse; inga CRAB-tecken kopplade till myelom",
     "Symtomatiskt/behandlingskrävande myelom: klonala plasmaceller + CRAB eller myelomdefinierande biomarkörer. Anemi, njursvikt, hyperkalcemi, skelettlesioner/fraktur, infektioner, trötthet, skelettsmärta"
    ],
    "k": "—",
    "d": "Misstanke: skelettsmärtor, anemi, hög SR, njursvikt, hyperkalcemi, återkommande infektioner eller patologisk fraktur utan annan förklaring. Myelom kan debutera diffust och missas som vanlig ryggsmärta eller åldersanemi (tentafråga: 'Vilka fynd gör att du misstänker myelom?') Basprover: blodstatus, diff, kreatinin/eGFR, kalcium/albumin, elektrolyter, leverprover, CRP/SR, albumin och beta-2-mikroglobulin. Kartlägger CRAB, inflammationsbild och prognostiska markörer ('Vilka prover beställer du initialt?') Monoklonal komponent: S-elfores, S-immunfixation, U-elfores/U-immunfixation eller urin för lätta kedjor, S-fria lätta kedjor och FLC-kvot.",
    "b": "MGUS: ingen myelombehandling; riskstratifierad provuppföljning (ingen organpåverkan och låg progressrisk per år) Smouldering myelom: vanligen observation, särskilt standardrisk; kontroller av M-komponent/FLC, blodstatus, kreatinin, kalcium och bild vid behov. Högriskfall bedöms av hematolog Nydebuterat symtomatiskt myelom, transplantationskandidat: induktionsbehandling följt av högdos melfalan och autolog stamcellstransplantation, därefter underhåll hos många. Kombination med proteasomhämmare, immunmodulerare, steroid och ofta CD38-antikropp beroende på aktuell rekommendation.",
    "m": "Akut njursvikt kan vara myelomdebut: undvik NSAID/dehydrering, behandla hyperkalcemi, snabb hematologkontakt (cast-nefropati kan bli irreversibel om lätta kedjor fortsätter skada tubuli)",
    "src": "t7-131"
   },
