   "card": {
    "fk": "Respiratorisk svikt ska delas upp i syresättningsproblem och ventilationsproblem. Vid syresättningssvikt är pO2/saturation låg. Vid ventilationssvikt stiger pCO2.",
    "v": [
     "Typ 1-svikt: hypoxemi utan hyperkapni. Vanliga orsaker är pneumoni, lungödem, ARDS, lungemboli och atelektas",
     "Typ 2-svikt: hyperkapni pga otillräcklig alveolär ventilation. Vanliga orsaker är KOL-exacerbation, opioid/sedering, neuromuskulär svaghet och uttröttning",
     "Postoperativ andningssvikt: hypoxi orsakas ofta av atelektas, smärta med ytlig andning, opioider/sedering, aspiration, lungödem, pneumoni eller lungemboli",
     "CPAP kan vara effektivt vid lungödem och postoperativ atelektas (förbättrar syresättningen).",
     "NIV (BiPAP) är särskilt indicerat vid hyperkapnisk (typ 2-)svikt, t.ex. KOL-exacerbation.",
     "Intubation och invasiv ventilation vid sviktande/hotad luftväg, sjunkande medvetandegrad eller när NIV inte räcker."
    ],
    "k": "",
    "d": "",
    "b": "Postoperativ andningssvikt – riktad behandling: smärtlindra så patienten kan andas djupt, mobilisera, ge PEP/andningsövningar, syrgas/CPAP vid behov och minska opioid/sedering om ventilationen är hämmad",
    "m": "Ventilationssvikt: pCO2 stiger och patienten riskerar respiratorisk acidos, trötthet och medvetandesänkning",
    "src": "t7-238"
   },
