   "card": {
    "fk": "Lymfom är en grupp maligna lymfatiska sjukdomar där behandlingen styrs av subtyp (Hodgkins lymfom, aggressiva respektive indolenta B-cellslymfom) och stadium.",
    "v": [
     "Hodgkins lymfom, klassiskt: lågt stadium (oftast I–II utan högriskfaktorer); tidigt stadium med riskfaktorer/bulky disease; avancerat stadium III–IV",
     "Hodgkins lymfom, nodulärt lymfocytdominerat (NLPHL): stadium I–II",
     "Aggressiva B-cellslymfom, särskilt DLBCL: lokaliserat stadium I–II; avancerat stadium III–IV; Burkittlymfom/primärt CNS-lymfom/PMBCL"
    ],
    "k": "—",
    "d": "—",
    "b": "Klassiskt, lågt stadium (oftast I–II utan högriskfaktorer): kurativ behandling med kortare cytostatikabehandling, ofta ABVD-baserad, följt av strålbehandling i många protokoll. PET-DT efter initial behandling är central för responsstyrning Klassiskt, tidigt stadium med riskfaktorer/bulky disease: mer intensiv eller längre cytostatikabehandling än vid lågrisk tidigt stadium, ofta med strålbehandling beroende på risk och PET-respons Klassiskt, avancerat stadium III–IV: kurativt syftande systemisk cytostatikabehandling, PET-adapterad.",
    "m": "'Lymfom' är inte en behandling, utan subtyp styr. Burkittlymfom/primärt CNS-lymfom/PMBCL behandlas enligt egna protokoll, inte som vanlig DLBCL",
    "src": "t7-130"
   },
