   "card": {
    "fk": "Akut pankreatit med epigastral smärta mot ryggen; behandlingen är främst stödjande plus etiologisk åtgärd. Gallstenspankreatit och infekterad pankreasnekros hanteras särskilt.",
    "v": [
     "Akut pankreatit: akut epigastral smärta med utstrålning rygg, illamående/kräkning, ofta gallsten eller alkohol. Svår form: SIRS, organsvikt. Likaså ileuslik bild kan förekomma",
     "Gallstenspankreatit: akut pankreatit med gallstensanamnes, kolestas eller sten på UL",
     "Infekterad pankreasnekros: feber/sepsis efter dagar-veckor vid svår pankreatit, gas i nekros på DT eller klinisk försämring"
    ],
    "k": "—",
    "d": "Diagnos: typisk smärta + lipas/amylas >3x normal eller bildfynd Prover: lipase/amylas, blodstatus, CRP, elektrolyter/krea, glukos, leverprover, triglycerider/kalcium vid behov. Bedöm vätska/diures Bild: UL gallvägar för gallstensorsak. DT buk med kontrast vid oklar diagnos, svår sjukdom eller utebliven förbättring/komplikation Gallstenspankreatit: UL, leverprover. MRCP/EUS vid misstänkt koledokussten Infekterad nekros: DT buk med kontrast när njurfunktion tillåter, odling vid intervention, bedömning på pankreas-/kirurgcentrum",
    "b": "Initialt: slutenvård, smärtlindring/opioider, rehydrering/iv vätska efter behov, antiemetika, tidig (enteral) nutrition när möjligt, övervakning av organpåverkan Orsaksriktat: ERCP vid kolangit/ihållande gallvägsobstruktion; kolecystektomi under samma vårdtillfälle vid mild gallstenspankreatit när återhämtad (senare vid svår sjukdom) Infekterad nekros: antibiotika och dränage vid behov. Step-up: perkutant/endoskopiskt dränage före nekrosektomi. Intervention skjuts ofta upp tills kapsel mognat om patienten tillåter; step-up-dränage/nekrosektomi sent vid behov",
    "m": "Ingen specifik botande behandling: stödjande vård + etiologisk åtgärd. Leta etiologi och komplikationer",
    "src": "t7-016"
   },
   "has_card": true,
