   "card": {
    "fk": "Njurcancer (cirka 1 300 nya fall per år i Sverige) är oftast klarcellig, papillär eller kromofob. Vanligast är numera ett incidentellt fynd vid bilddiagnostik (64 % år 2023).",
    "v": [
     "Symtom ofta ospecifika eller uteblir",
     "Klassiska tecken: makroskopisk hematuri, flanksmärta, palpabel resistens i flanken",
     "Nydebuterat varicocele som inte töms i liggande ger misstanke"
    ],
    "k": "—",
    "d": "Första val: DT njurar/urinvägar i flera faser (utan och med kontrast) + DT thorax Vid nedsatt njurfunktion: MRT eller kontrastultraljud Perkutan mellannålsbiopsi vid oklar malignitet, särskilt små tumörer Cystiska förändringar: Bosniak (2019); Bosniak III–IV = välgrundad misstanke Gradering WHO/ISUP, stadium TNM (UICC 2017)",
    "b": "Icke-metastaserad: kirurgi förstahand; partiell nefrektomi rekommenderas för T1 när tekniskt möjligt; ablation, aktiv monitorering och adjuvant pembrolizumab kan övervägas i utvalda fall Metastaserad/återfall: immunologiska kombinationer och tyrosinkinashämmare, val enligt IMDC-riskklassificering; kirurgi, strålning, skelettstärkande vid behov; MDK rekommenderas",
    "m": "Nydebuterat varicocele som inte töms i liggande = misstänk njurcancer",
    "src": "t7-214"
   },
