    "fk": "Navelbråck är en fasciedefekt i/kring navelringen. Hos vuxna läker det inte spontant på samma sätt som hos barn.",
    "v": [
     "Lokalisation: fasciedefekt i/kring navelringen",
     "Risk: övervikt, graviditet, ascites, bindvävssvaghet. Hos vuxna läker det inte spontant på samma sätt som hos barn",
     "Symtom/fynd (navel-/epigastrikabråck): medellinjeutbuktning, ofta vid ökat buktryck; smärta vid inklämning av fett/tarm",
     "Lokalisation: i linea alba mellan navel och processus xiphoideus",
     "Typiskt: ofta små defekter med preperitonealt fett; ibland multipla",
     "Lokalisation: genom femoralkanalen under inguinalligamentet, medialt om v. femoralis"
    ],
    "k": "",
    "d": "Klinisk diagnos. Ultraljud/DT vid oklar anatomi, obesitet, operationsplanering eller akut buk",
    "b": "Metod: små defekter kan ibland sutureras; nätplastik ger lägre recidiv vid många vuxna/särskilt större defekter",
    "m": "Klinisk tentapoäng: små portar kan klämma in tarm/fett; symtomgivande eller tillväxande bråck kan opereras",
