   "card": {
    "fk": "Akut mesenteriell ischemi är en tidskritisk diagnos med hög mortalitet, ofta orsakad av emboli/trombos i a. mesenterica superior vid förmaksflimmer/ateroskleros. Kronisk form (bukangina) ger postprandiell smärta.",
    "v": [
     "Akut mesenteriell ischemi: smärta \"out of proportion\", ofta förmaksflimmer/ateroskleros, initialt diskret bukstatus, senare peritonit/laktat/chock",
     "Akut mesenterial ischemi (bukorgansischemi): ofta emboli/trombos i a. mesenterica superior, särskilt vid FF/ateroskleros. Plötslig svår buksmärta, ofta mer ont än bukstatus visar; illamående, diarré/blod, laktat/metabol acidos sent",
     "Bukangina/kronisk mesenterial ischemi: aterosklerotiska stenoser i mesenterialkärl, oftast krävs påverkan av flera kärl pga kollateraler. Postprandiell buksmärta, maträdsla, viktnedgång, diarré. Ofta generell ateroskleros"
    ],
    "k": "—",
    "d": "Basprover och bedside: blodgas/laktat (kan vara normalt tidigt), blodstatus, CRP, elektrolyter/krea, koagulation. EKG/embolikällor Bild: DT-angio/DT buk med iv kontrast med tydlig frågeställning akut tarmischemi. Snabb kontakt kirurg/kärlkirurg DT-angio/DT buk med artärfas utan fördröjning. Lab kan stödja men utesluter inte Kronisk form: DT-angio av mesenterialkärl, ev duplex på specialiserad enhet",
    "b": "Initial behandling på akuten: ABCDE, vätska, smärtlindring, antibiotika vid peritonit/nekrosmisstanke, antikoagulation ofta efter bedömning, kirurg/kärlkirurg akut Akut kärl-/kirurgkontakt, vätska, bredspektrumantibiotika vid tarmskada/sepsis, heparin Definitiv/orsaksriktad: endovaskulär revaskularisering/trombolys/trombektomi eller öppen kirurgi. Laparotomi vid peritonit/nekros; resektionsbeslut och second look kan behövas. Revaskularisering endovaskulär/öppen + laparotomi vid peritonit/nekros Kronisk form: riskfaktorkontroll och revaskularisering, ofta endovaskulär stent/angioplastik av framför allt SMA",
    "m": "Tidskritisk diagnos med hög mortalitet. Snabb bild och revaskularisering/laparotomi vid behov",
    "src": "t7-050"
   },
