   "card": {
    "fk": "Benigna orsaker till svullen pung: hydrocele (vätska kring testikeln), spermatocele (cysta mellan testikel och bitestikel) och varicocele (utvidgade vener). Bråck, inflammation, torsion och cancer är differentialdiagnoser.",
    "v": [
     "Tyngd/obehag; vänster sida ofta något större normalt",
     "Varicocele: vänster oftast; upp till 20 % av män; oftast symtomfri, ibland smärta eller störd testikelfunktion",
     "Hydrocele: vätska kring testikeln"
    ],
    "k": "—",
    "d": "Palpation; ultraljud vid misstänkt cancer Varikocele: erfaren läkare bedömer storlek",
    "b": "Suspensorium kan lindra Hydrocele: oftast ofarlig; kirurgi vid besvär Spermatocele: oftast ofarlig; vid besvär nålpunktion (± skleroserande) eller sällan kirurgi Varikocele: ofta ingen behandling; kirurgi eller embolisering/coiling vid påverkad tillväxt hos tonåringar eller spermakvalitet; resultat omtvistade; spermaprov 4–6 mån efter",
    "m": "Plötslig, smärtsam svullnad = akut skrotum",
    "src": "t7-221"
   },
