   "card": {
    "fk": "Esofaguscancer, adenocarcinom och skivepitelcancer, med olika riskprofil och behandling.",
    "v": [
     "Adenocarcinom: progressiv dysfagi, viktnedgång, regurgitation, anemi. Risk: Barrett/GERD, obesitas, manligt kön",
     "Skivepitelcancer: dysfagi, odynofagi, viktnedgång. Risk: rökning, alkohol, tidigare strålning, achalasi"
    ],
    "k": "—",
    "d": "Adenocarcinom: SVF. Gastroskopi med biopsi är nyckel. Staging med DT thorax/buk, PET-DT och EUS enligt tumörläge/stadium; nutritionsbedömning och MDK Skivepitelcancer: som ovan: gastroskopi+biopsi, DT/PET, EUS, bronkoskopi vid högt sittande tumör vid behov",
    "b": "Adenocarcinom, kurativ: multimodal behandling. Esofagektomi med rekonstruktion hos utvalda; ofta neoadjuvant/perioperativ onkologisk behandling beroende på stadium Skivepitelcancer, kurativ: kemoradioterapi kan vara central; kirurgi hos selekterade beroende på lokalisation och respons",
    "m": "Dysfagi + viktnedgång = cancer tills motsatsen visad",
    "src": "t7-008"
   },
