   "card": {
    "fk": "Godartade hudförändringar övergår enligt 1177 inte i cancer men kan förväxlas med hudcancer. Exempel: melanocytära nevi (födelsemärken), seborroisk keratos, dermatofibrom och lentigo solaris.",
    "v": [
     "Melanocytärt nevus: lokal ökning av melanocyter, medfött eller förvärvat; typer junction-, intradermalt, sammansatt och medfött nevus; speciella former Spitz, Reeds, blått nevus, halonevus. De flesta förvärvade, ökar fram till 50 års ålder;",
     "Seborroisk keratos (åldersvårta): upphöjd, fet/glänsande eller torr fjällande yta, ljusbrun till gråsvart; vanligast ansikte, bröst, rygg",
     "Dermatofibrom: hård brunröd/brun knuta, oftast ljus i mitten, dras inåt vid klämtest; oftast ben/armar"
    ],
    "k": "—",
    "d": "Hudstatus med helkroppsundersökning; bedöm hudtyp, antal stora (>5 mm) och små (<5 mm) nevi Ugly duckling: nevus som skiljer sig från övrig hudkostym; bedöm lokalisation, storlek, färg, form, avgränsning, upphöjning Dermatoskopi: junctionnevus jämnt pigmentnätverk; intradermalt globulärt/kullerstensmönster utan nätverk; sammansatt globulärt mönster med nätverk perifert. Använd dermatoskopi/teledermatoskopi vid tveksamhet Dysplastiskt nevus är en histopatologisk diagnos som bara patolog kan ställa",
    "b": "Typiskt melanocytärt nevus: excision bör inte göras inom offentligt finansierad vård, inte heller av kosmetiska skäl Dermatofibrom: opereras bort vid osäker diagnos eller stora besvär Borttagning av godartade förändringar sker oftast mot egen kostnad",
    "m": "Ny eller förändrad pigmentfläck kan vara hudcancer – godartat måste avgöras kliniskt/dermatoskopiskt",
    "src": "t7-072"
   },
   "has_card": true,
