   "card": {
    "fk": "Kirurgi vid ulcerös kolit görs vid svårt skov som inte svarar på medicinsk behandling, komplikationer, steroidberoende sjukdom samt dysplasi/cancer. Kumulativ livstidsrisk för tarmkirurgi 25–30 %. Vid akut kolit gäller att målet är att rädda livet, inte tarmen.",
    "v": [
     "Indikationer för kolektomi vid svårt skov: utebliven effekt av medicinsk behandling, toxisk kolondilatation, hotande/manifest perforation, akut svår kolorektal blödning, utebliven förbättring 4–5 dagar efter start av rescue-behandling",
     "Övriga indikationer: kronisk kontinuerlig sjukdom med steroidberoende (vuxna) eller nedsatt tillväxt/försenad pubertet (barn); dysplasi och/eller cancer; rekonstruktion efter tidigare kolektomi",
     "Svårt skov: ca 15 % drabbas någon gång; blodig diarré, uttalad buksmärta, feber, viktminskning. Patienten kan se anmärkningsvärt opåverkad ut",
     "Akut kirurgi är undantag: fri perforation, misstänkt ischemi, profus GI-blödning, terapiresistent akut kolit, fulminant ileus som inte svarar på avlastning",
     "Elektiv: kronisk tunntarmsstenos utan ischemi/peritonit; prestenotisk dilatation >3 cm är kliniskt signifikant",
     "Abscess: perkutan dränering först (lyckas i 65–100 %), kirurgi vid otillräcklig effekt"
    ],
    "k": "",
    "d": "Inläggning, gemensam handläggning av gastroenterolog och kolorektal kirurg Rektoskopi/sigmoideoskopi och buköversikt omedelbart; kolonröntgen med kontrast är kontraindicerad Utesluta infektion: feceskultur, C. difficile-toxin; ischemisk kolit är differentialdiagnos hos äldre Daglig övervakning: temperatur, puls, bukstatus, antal avföringar, Hb, CRP, SR, albumin, trombocyter Bedömning dag 3 (Sverigeindex): antal tarmtömningar + 0,14 × CRP (mg/l); index <8 ger 16 % kolektomi inom 30 dagar, index >8 ger 72 % – då övervägs rescue eller kolektomi",
    "b": "Kortison iv: betametason 8 mg/dag (eller ekvipotent) minst 5 dagar; ca hälften remission, ca 30 % steroidresistenta Rescue: infliximab 5 mg/kg engångsinfusion (kolektomi 29 % vs 67 % placebo efter 3 mån); ciklosporin är alternativ men hög recidivfrekvens Operation vid akut kolit/kronisk kontinuerlig kolit: tvåstegsförfarande – kolektomi med ileostomi och kvarlämnat rektum, rekonstruktion senare Cancer: proktokolektomi med bäckenreservoar (IPAA) förstahandsval; TME vid cancer; dysplasi bör bekräftas av minst två erfarna GI-patologer Rekonstruktion: IPAA (standard i ca 25 år), oftast i två etapper med tillfällig loop-ileostomi; alternativ: ileorektalanastomos (selekterade), permanent ileostomi, Kock-reservoar",
    "m": "Medicinsk behandling får inte fördröja nödvändig operation – målet är att rädda livet",
    "src": "t7-026"
   },
