   "card": {
    "fk": "Infektion i operationsområdet som omfattar huden och subkutis ned till fascian. Postoperativ infektion definieras (Viss.nu) som ytlig eller djup infektion i operationsområdet som debuterar inom 30 dagar efter kirurgi utan implantat eller inom 1 år med implantat.",
    "v": [
     "Debut: vanligen 5-10 dagar postoperativt, men kan ses redan efter ett dygn eller först efter utskrivning",
     "Lokalt: ny eller ökad smärta (ofta bultande), rodnad, värmeökning, svullnad, ökad eller purulent sekretion, dålig lukt",
     "Allmänt: feber kan vara första tecknet; allmänpåverkan vid spridning"
    ],
    "k": "—",
    "d": "Diagnosen är i första hand klinisk; palpera efter abscess, fluktuation, krepitation, ömhet Odling om antibiotika övervägs (djupt från gränsen mot frisk vävnad), särskilt vid nyligen sjukhusvistelse/utlandsvistelse, behandlingssvikt, systemtecken, MRSA-misstanke Vid misstänkt spridd infektion: Hb, CRP, LPK med diff, blodtryck, puls, temperatur Ultraljud kan påvisa abscess och djupare ödem",
    "b": "Grunden är kirurgisk: öppna såret (ta bort suturer, öppna infekterad del brett), dränera var, ev. debridera; vid abscess incision och dränage Antibiotika behövs ofta inte; ges om kirurgisk revision bedöms otillräcklig, vid djupare vävnadsengagemang eller vid omfattande infiltrat med feber/allmänpåverkan Dosexempel enligt Viss.nu (vuxna, sårinfektion): flukloxacillin 1 g x 3 i 7 dygn; vid PC-allergi klindamycin 300 mg x 3 i 7 dygn Vid okomplicerad abscess upp till cirka 5 cm räcker oftast incision och dränage; antibiotika behövs i regel inte (Läkartidningen). Gramnegativa bakterier ska normalt inte behandlas (Viss.nu)",
    "m": "Nekrotiserande fasciit: smärta oproportionerligt kraftig, krepitation eller blågrå hud, kräver akut bedömning",
    "src": "t7-090"
   },
