    "k": "",
    "d": "Kolonileus: ABCDE vid påverkan; blodprover inkl elektrolyter, CRP, laktat vid ischemimisstanke; DT buk med kontrast för nivå, orsak, ischemitecken och perforation; koloskopi inte primärt vid akut ileus Peritoneal metastasering: DT buk för nivå, antal hinder och operabilitet; bedöm performance status, nutrition, sjukdomsutbredning och behandlingsmål",
    "b": "Kolonileus: vätska, elektrolytkorrigering, ventrikelsond vid kräkning, smärtlindring, kirurgkontakt Kolonileus, definitivt: akut resektion, avlastande stomi eller endoskopisk stent som brygga till elektiv kirurgi hos selekterade Peritoneal metastasering, symtomlindring: vätskeavvägning, antiemetika, opioid, antisekretorisk behandling, steroider i vissa fall Peritoneal metastasering: stent/stomi/kirurgi endast vid rimlig nytta och teknisk möjlighet; tidig palliativ vård",
