    "d": "Diagnos: upprepat förhöjt albuminkorrigerat Ca eller joniserat Ca med PTH som är förhöjt eller inadekvat normalt. Kontrollera kreatinin/eGFR, fosfat, 25-OH-D-vitamin Utredning inför operation: DXA/bentäthet, njurfunktion, dygnsurin-Ca eller calcium/kreatinin-clearancekvot, njurstensanamnes/bild vid behov Lokalisation: ultraljud paratyreoidea + sestamibi/SPECT-CT; ibland 4D-CT",
    "b": "Operationsindikationer: symtomgivande PHPT bör erbjudas operation om patienten tål det. Asymtomatisk PHPT: operation vid t.ex. yngre ålder, tydligt förhöjt Ca, skelettpåverkan/osteoporos/fraktur, njursten/njurpåverkan eller hyperkalciuri enligt vårdprogram/lokal bedömning Behandling: paratyreoidektomi är enda kurativa behandling. Fokuserad operation vid tydligt lokaliserat adenom; bilateral exploration vid oklar/multiglandulär sjukdom Om ej operation: uppföljning Ca/njure/skelett, D-vitaminoptimering, cinakalcet/bisfosfonat i särskilda fall",
    "m": "Tentafälla: lokaliserande bilddiagnostik ställer inte diagnosen; diagnosen är biokemisk. Bilddiagnostik används för att planera operation",
