   "card": {
    "fk": "Peritonit (perforerat ulcus/fri gas/sekundär peritonit) och intraabdominell abscess: infektioner i buken där source control är den avgörande frågan.",
    "v": [
     "Perforerat ulcus/fri gas/sekundär peritonit: plötslig svår epigastral smärta, brädhård buk, peritonit, takykardi, ibland chock/sepsis. Kan ha NSAID/ulcus-anamnes",
     "Intraabdominell abscess: feber, CRP, fokal buksmärta, ofta efter appendicit/divertikulit/kirurgi. Kan ge sepsis eller ileusbild"
    ],
    "k": "—",
    "d": "Perforerat ulcus: ABCDE, blodgas/laktat, blodstatus, CRP, elektrolyter/krea, leverprover, BAS-test, EKG som differential. DT buk med kontrast om stabil; fri gas. Vid uppenbar peritonit kan operation prioriteras utan onödig väntan Intraabdominell abscess: blodstatus, CRP, odlingar vid feber/sepsis, vätskestatus. Leta bakomliggande fokus. DT buk med kontrast visar abscess och styr dränage. UL kan användas för ytliga/leverrelaterade abscesser",
    "b": "Perforerat ulcus/sekundär peritonit, initialt: ABCDE, fasta, grova infarter, vätska, bredspektrumantibiotika, PPI, ventrikelsond, analgesi, BAS/MG Perforerat ulcus, definitivt: akut laparoskopi/laparotomi med sutur/omentpatch och peritoneal lavage. Non-operativ behandling endast i mycket selekterade fall utan fri läcka/stabil patient Intraabdominell abscess, initialt: antibiotika om allmänpåverkad/sepsis, vätska och smärtlindring. Odla om möjligt Intraabdominell abscess, definitivt: perkutant bildstyrt dränage om åtkomlig abscess. Kirurgiskt dränage/operation om otillgänglig, peritonit eller bakomliggande perforation kräver åtgärd",
    "m": "Perforerat ulcus/peritonit: tid till operation påverkar prognosen; vänta inte på \"perfekta\" prover om patienten försämras",
    "src": "t7-003"
   },
   "has_card": true,
