    "v": [
     "Ansträngningsinkontinens: skvättvis läckage vid hosta, nysning, lyft; vanligast hos kvinnor före menopaus (bäckenbotten); hos män efter radikal prostatakirurgi",
     "Trängningsinkontinens/överaktiv blåsa: täta, plötsliga trängningar, nykturi; orsaker ålder, neurologi, UVI, läkemedel, prostataförstoring, förstoppning",
     "Blandinkontinens: vanligast hos äldre kvinnor",
     "Neurogen blåsrubbning (t.ex. stroke, MS, demens, ryggmärgsskada, cauda equina, diabetesneuropati) kan ge inkontinens och/eller tömningssvårigheter."
    ],
    "k": "",
    "d": "Miktionslista två dygn, vätskelista, läckagetyp/mängd i vikt, tarmfunktion, läkemedel, graviditet/förlossning, tidigare bäckenkirurgi, BMI Residualvolym med blåsscanner; män tidsmiktion vid misstänkt försämrad tömning Urinodling vid misstänkt UVI (urinsticka bör generellt undvikas); asymtomatisk bakteriuri behandlas inte rutinmässigt Urodynamik/cystometri vid kraftigt avvikande lista, neurologisk misstanke eller komplicerad kirurgiindikation (Dalarna)",
    "b": "Rådgivning: vätske- och koffeinintag, tarmfunktion, toalettvanor, viktminskning, rökstopp Bäckenbottenträning: effektiv vid ansträngningsinkontinens; blåsträning vid trängningar Läkemedel: antikolinergika, beta-3-agonister och botulinumtoxin A vid överaktiv blåsa; duloxetin vid ansträngningsinkontinens; lokalt östrogen hos postmenopausala kvinnor; desmopressin vid nattlig polyuri Kirurgi ansträngningsinkontinens: TVT/TOT, ca 80 % bot efter 1 år; trängningsinkontinens opereras inte Överrinning: åtgärda avflödeshindret; RIK vid försvagad blåsmuskel Tibialis-stimulering vid trängnings-/blandinkontinens; RIK och botulinumtoxin vid svår blandinkontinens/neurogen blåsrubbning",
    "m": "Plötslig debut av trängningar kan vara symtom på tumör i urinblåsa, prostata eller äggstockar",
