   "card": {
    "fk": "Binjuretumörer från incidentalom till hormonproducerande tumör: binjureincidentalom, feokromocytom, primär aldosteronism, Cushings syndrom/kortisolproducerande tumör och binjurebarkscancer (ACC).",
    "v": [
     "Binjureincidentalom: ofta slumpfynd. Aktivt fråga efter attacker, hypertoni, hypokalemi, viktuppgång, blåmärken, diabetes, muskelsvaghet, tidigare malignitet",
     "Feokromocytom: paroxysmal eller ihållande hypertoni, huvudvärk, svettning, palpitationer, tremor, blekhet, panikattacker. Kan utlösas av anestesi/biopsi",
     "Primär aldosteronism: hypertoni, ibland hypokalemi, muskelsvaghet, metabol alkalos. Vanlig orsak till sekundär hypertoni"
    ],
    "k": "—",
    "d": "Incidentalom: DT: storlek, densitet HU, kontrast washout/fettinnehåll. Hormonellt: 1 mg dexametasonhämning för kortisolautonomi; metanefriner vid misstanke/icke typiskt benignt adenom; aldosteron/renin-kvot vid hypertoni/hypokalemi Feokromocytom: plasma fria metanefriner eller urinmetanefriner. DT/MR. Genetik ofta aktuell. Undvik biopsi innan feokromocytom uteslutits Primär aldosteronism: aldosteron/renin-kvot, bekräftande tester enligt endokrinolog, DT binjurar. Binjurevenskateterisering för lateraliseringsdiagnostik när kirurgi övervägs Cushings syndrom: 1 mg dexametasonhämning, kortisol/ACTH för ACTH-beroende/oberoende, DT binjurar.",
    "b": "Incidentalom: adrenalektomi vid hormonproducerande tumör, malignitetsmisstanke eller tillväxt/radiologiskt suspekt lesion. Benign icke-funktionell lesion följs/avslutas enligt risk Feokromocytom: alfa-blockad först, volymoptimering, därefter kirurgi. Betablockad endast efter alfa-blockad om takykardi kräver Primär aldosteronism: unilateral aldosteronproducerande adenom: adrenalektomi. Bilateral hyperplasi: mineralkortikoidreceptorantagonist Cushings syndrom: unilateral kortisolproducerande tumör: adrenalektomi. Postop behövs ofta hydrokortisonsubstitution tills HPA-axeln återhämtar sig ACC: radikal kirurgi i expertcentrum om resektabel. Mitotan och onkologisk behandling vid avancerad sjukdom",
    "m": "Feokromocytom: aldrig operation/biopsi utan biokemisk diagnos och alfa-blockad/volymoptimering",
    "src": "t7-065"
   },
